/**
 * Canonical Suzent Logo (24x24, rx=4) geometry, 25 expressive 48-point eye pairs,
 * Catmull-Rom -> Cubic Bezier spline helpers, and 4-sided 3D perspective turn math.
 *
 * Extracted 1:1 from the Suzent x GrokBot v14 reference engine.
 */

export type Point2D = [number, number];
export type EyePair = [Point2D[], Point2D[]];

export const HEAD_C = 114.2705;
export const EYE_HALF = 21;
export const SUZENT_TOP = 0.05;
export const SUZENT_BOTTOM = 228.49;
export const SUZENT_RADIUS = 136.95;
export const SUZENT_BELT_RADIUS = 114.22;
export const SUZENT_TILT_SCALE = 0.92;

export function clamp(val: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, val));
}

export function centroid(ring: readonly Point2D[]): Point2D {
  let x = 0;
  let y = 0;
  for (const pt of ring) {
    x += pt[0];
    y += pt[1];
  }
  const n = ring.length || 1;
  return [x / n, y / n];
}

export function lerpRing(
  from: readonly Point2D[],
  to: readonly Point2D[],
  amount: number,
): Point2D[] {
  return from.map(([x, y], index) => [
    x + (to[index][0] - x) * amount,
    y + (to[index][1] - y) * amount,
  ]);
}

export function ringPath(ring: readonly Point2D[]): string {
  return `M${ring.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join("L")}Z`;
}

export function ringOutline(ring: readonly Point2D[]): string {
  const round = (v: number) => Math.round(v * 100) / 100;
  const len = ring.length;
  let path = `M${round(ring[0][0])} ${round(ring[0][1])}`;
  for (let i = 0; i < len; i += 1) {
    const prev = ring[(i - 1 + len) % len];
    const pt = ring[i];
    const next = ring[(i + 1) % len];
    const after = ring[(i + 2) % len];
    path += `C${round(pt[0] + (next[0] - prev[0]) / 6)} ${round(pt[1] + (next[1] - prev[1]) / 6)} ${round(next[0] - (after[0] - pt[0]) / 6)} ${round(next[1] - (after[1] - pt[1]) / 6)} ${round(next[0])} ${round(next[1])}`;
  }
  return `${path}Z`;
}

export function spanAt(ring: readonly Point2D[], y: number): [number, number] {
  let left = -Infinity;
  let right = Infinity;
  for (let i = 0; i < ring.length; i += 1) {
    const start = ring[i];
    const end = ring[(i + 1) % ring.length];
    if (start[1] <= y === end[1] <= y) continue;
    const x =
      start[0] + ((end[0] - start[0]) * (y - start[1])) / (end[1] - start[1]);
    if (x <= HEAD_C) left = Math.max(left, x);
    else right = Math.min(right, x);
  }
  return [
    Number.isFinite(left) ? left : HEAD_C,
    Number.isFinite(right) ? right : HEAD_C,
  ];
}

