export function suzentSpanAt(
  ring: readonly Point2D[],
  y: number,
): [number, number] {
  if (!SUZENT_SPAN_SAMPLES.length) return spanAt(ring, y);
  const count = SUZENT_SPAN_SAMPLES.length;
  const position = clamp(
    ((y - SUZENT_TOP) / (SUZENT_BOTTOM - SUZENT_TOP)) * count - 0.5,
    0,
    count - 1,
  );
  const start = Math.floor(position);
  const end = Math.min(start + 1, count - 1);
  const amount = position - start;
  return [
    SUZENT_SPAN_SAMPLES[start][0] +
      (SUZENT_SPAN_SAMPLES[end][0] - SUZENT_SPAN_SAMPLES[start][0]) * amount,
    SUZENT_SPAN_SAMPLES[start][1] +
      (SUZENT_SPAN_SAMPLES[end][1] - SUZENT_SPAN_SAMPLES[start][1]) * amount,
  ];
}

export function turnedSuzentRing(
  ring: readonly Point2D[],
  angle: number,
): Point2D[] {
  const sides = 4;
  const segment = (Math.PI * 2) / sides;
  const factor =
    1 +
    (Math.cos((((angle % segment) + segment) % segment) - segment / 2) /
      Math.cos(segment / 2) -
      1) *
      0.45;
  return ring.map(([x, y]) => [HEAD_C + (x - HEAD_C) * factor, y]);
}

